const now = new Date();
const todayStr = now.toISOString().slice(0, 10);
const leads = $input.all().map(i => i.json);

const counts = { New: 0, Contacted: 0, Booked: 0, Stale: 0 };
let newToday = 0;
let bookedToday = 0;
const escalations = [];

for (const lead of leads) {
  const status = (lead['Status'] || '').trim();
  if (counts[status] !== undefined) counts[status]++;

  const created = String(lead['Date Created'] || '').slice(0, 10);
  if (created === todayStr) newToday++;

  const lastContact = String(lead['Last Contact'] || '').slice(0, 10);
  if (status === 'Booked' && lastContact === todayStr) bookedToday++;

  const temp = (lead['Temperature'] || '').trim();
  if (status === 'Stale' && (temp === 'Hot' || temp === 'Warm')) {
    escalations.push({
      leadId: lead['Lead ID'] || '',
      name: [lead['First Name'], lead['Last Name']].filter(Boolean).join(' ') || 'Unknown',
      temp,
      score: (lead['Lead Score'] !== undefined && lead['Lead Score'] !== '') ? lead['Lead Score'] : '?',
      phone: lead['Phone'] || ''
    });
  }
}

// SETUP REQUIRED: replace with owner/rep E.164 phone — same number as workflow 04 Build Alert Message
const OWNER_PHONE = 'OWNER_PHONE_HERE';

let msg = 'Daily Pipeline - Valfin Tech\n';
msg += 'New ' + counts.New + ' | Contacted ' + counts.Contacted + ' | Booked ' + counts.Booked + ' | Stale ' + counts.Stale + '\n';

if (escalations.length) {
  msg += '\nNeeds your personal touch (Stale + Hot/Warm):\n';
  escalations.slice(0, 3).forEach(e => {
    msg += e.leadId + ' ' + e.name + ' (' + e.temp + ' ' + e.score + ') ' + e.phone + '\n';
  });
  if (escalations.length > 3) msg += '+' + (escalations.length - 3) + ' more\n';
}

msg += '\nToday: ' + newToday + ' new, ' + bookedToday + ' booked';

return [{ json: {
  digestMessage: msg.trim(),
  ownerPhone: OWNER_PHONE,
  counts,
  escalationCount: escalations.length,
  newToday,
  bookedToday
} }];
